import React, { useState } from 'react';

export default function SearchBar({ onSearch }) {
  const [query, setQuery] = useState('');
  const [subject, setSubject] = useState('');

  function submit(e) {
    e.preventDefault();
    onSearch({ q: query, subject });
  }

  return (
    <div className="bg-gradient-to-r from-indigo-50 to-purple-50 rounded-xl p-6 mb-8 shadow-sm border border-indigo-100">
      <form onSubmit={submit} className="flex flex-col md:flex-row gap-4">
        <div className="flex-1 relative">
          <input
            className="w-full border-2 border-gray-200 rounded-lg px-4 py-3 pl-10 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 transition-all outline-none text-gray-700 placeholder-gray-400"
            placeholder="Search notes by title, description, or keyword..."
            value={query}
            onChange={e => setQuery(e.target.value)}
          />
          <svg className="absolute left-3 top-3.5 h-5 w-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
          </svg>
        </div>
        <div className="md:w-56 relative">
          <input
            className="w-full border-2 border-gray-200 rounded-lg px-4 py-3 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 transition-all outline-none text-gray-700 placeholder-gray-400"
            placeholder="Subject (e.g., Math, Physics)"
            value={subject}
            onChange={e => setSubject(e.target.value)}
          />
        </div>
        <button 
          className="bg-indigo-600 text-white rounded-lg px-6 py-3 font-semibold hover:bg-indigo-700 transition-all duration-200 shadow-md hover:shadow-lg transform hover:-translate-y-0.5 whitespace-nowrap" 
          type="submit"
        >
          <span className="flex items-center justify-center gap-2">
            <svg className="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
            </svg>
            Search
          </span>
        </button>
      </form>
    </div>
  );
}
